final class PlaybillExperience
{
    private const ROUTES=['/playbills','/playbill/consent','/admin/playbill'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        $db=Database::connect(dirname(__DIR__));
        Auth::startSession();$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['playbill_csrf']??=bin2hex(random_bytes(24));$production=ProductionContext::selected($db,$user);
        if($route==='/playbill/consent')self::ownConsent($db,$basePath,$user,(int)$_GET['profile']);
        if($route==='/admin/playbill'){
            if(!AccessPolicy::canManagePlaybill($user))self::forbidden();
            $requested=(int)($_GET['production']??0);
            if($requested){$q=$db->prepare('SELECT * FROM productions WHERE id=?');$q->execute([$requested]);$production=$q->fetch()?:null;}
            if($production&&!PlaybillStudioService::canEdit($db,$user,(int)$production['id']))self::forbidden();
            $pb=$production?self::playbillForProduction($db,(int)$production['id']):null;
            if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$basePath,$user,$production);
            if($pb&&!empty($_GET['preview_asset'])){$v=PlaybillStudioService::previewAsset($db,$pb,(string)($_GET['kind']??''),(int)($_GET['id']??0));header('Cache-Control: private, no-store');if(!$v){http_response_code(404);exit('Preview image unavailable.');}StorageService::stream(dirname(__DIR__),$v,false);}
            if($pb&&!empty($_GET['preview'])){$pb['_preview']=true;[$sections,$company,$team,$sponsors]=PlaybillStudioService::presentation($db,$pb,true);PlaybillPublicRenderer::render($basePath,$pb,$sections,$company,$team,$sponsors);}
            if($pb&&!$pb['public_enabled']&&in_array($production['lifecycle_stage'],['upcoming','planning','in_production','performing'],true)&&$pb['editorial_status']!=='archived')PlaybillEnhancementService::syncCastProfiles($db,(int)$pb['id'],(int)$production['id'],(int)$user['id']);
            PlaybillStudio::render($db,$basePath,$user,$production,$pb);
        }
        $playbill=$production?self::playbillForProduction($db,(int)$production['id']):null;
        if($playbill&&$playbill['public_enabled']&&in_array($playbill['editorial_status'],['published','archived'],true))self::redirect($basePath.'/playbill?slug='.rawurlencode($playbill['public_slug']));
        self::page($db,$route,$basePath,$user,$production,null,[],[]);
    }

    private static function ownConsent(PDO $db,string $base,array $user,int $id):never
    {
        $q=$db->prepare('SELECT p.*,pb.display_title,pr.title production_title FROM playbill_cast_profiles p JOIN playbills pb ON pb.id=p.playbill_id JOIN productions pr ON pr.id=pb.production_id WHERE p.id=?');$q->execute([$id]);$profile=$q->fetch();$allowed=$profile&&(int)$profile['user_id']===(int)$user['id'];if($profile&&!$allowed&&IdentityRolePolicy::isStudent($db,(int)$profile['user_id'])){$g=$db->prepare("SELECT 1 FROM family_relationships fr JOIN users child ON child.id=fr.student_user_id AND child.active=1 AND child.account_status='active' WHERE fr.student_user_id=? AND fr.guardian_user_id=? AND fr.status='active' AND fr.relationship_type IN ('parent','guardian')");$g->execute([(int)$profile['user_id'],(int)$user['id']]);$allowed=(bool)$g->fetchColumn();}if(!$allowed){http_response_code(404);exit('Publication profile unavailable.');}
        if(!empty($_GET['headshot'])){$v=$profile['headshot_stored_file_id']?StorageService::currentVersion($db,(int)$profile['headshot_stored_file_id']):null;header('Cache-Control: private, no-store');if(!$v||!in_array($v['mime_type'],['image/jpeg','image/png','image/webp'],true)){http_response_code(404);exit('Profile image unavailable.');}StorageService::stream(dirname(__DIR__),$v,false);}
        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!hash_equals($_SESSION['playbill_csrf'],(string)($_POST['csrf_token']??''))){http_response_code(403);exit('Your form session expired.');}
            try{PlaybillEnhancementService::decideCastApproval($db,$user,$id,(string)($_POST['decision']??''));$_SESSION['playbill_flash']=['type'=>'success','message'=>'Publication consent updated.'];}catch(RuntimeException $e){$_SESSION['playbill_flash']=['type'=>'error','message'=>$e->getMessage()];}
            self::redirect($base.'/playbill/consent?profile='.$id);
        }
        $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$u=static fn(string $p):string=>$base.$p;$name=$profile['display_name'];if(IdentityRolePolicy::isStudent($db,(int)$profile['user_id'])){$q=$db->prepare('SELECT first_name,last_name FROM users WHERE id=?');$q->execute([(int)$profile['user_id']]);$child=$q->fetch();$name=PlaybillStudioService::studentName($child['first_name'],$child['last_name']);}$flash=$_SESSION['playbill_flash']??null;unset($_SESSION['playbill_flash']);header('Content-Type:text/html; charset=utf-8');header('Cache-Control: private, no-store');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review my publication profile</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><?php WorkspaceUI::operationsStyles($base);?><link rel="stylesheet" href="<?=$u('/assets/css/playbill-studio.css')?>"></head><body class="app-body ux-workspace ux-operations"><div class="unified-shell"><?php AppNavigation::renderSidebar('/playbills',$base,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('My Theatre','My publication profile',$base);?><div class="studio"><section class="studio-panel"><h2><?=$e($profile['display_title']?:$profile['production_title'])?></h2><?php if($flash):?><p role="status"><?=$e($flash['message'])?></p><?php endif;?><h3><?=$e($name)?></h3><?php if($profile['headshot_stored_file_id']):?><img class="studio-sponsor-thumb" src="<?=$u('/playbill/consent?profile='.$id.'&headshot=1')?>" alt="Program portrait for <?=$e($name)?>"><?php endif;?><p><?=$e($profile['role_title'])?></p><p><?=nl2br($e($profile['biography']))?></p><p>Consent: <?=$e($profile['approval_status'])?>. Approval applies to this program snapshot, not your shared account profile. You may withdraw it later.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e($_SESSION['playbill_csrf'])?>"><button class="button" name="decision" value="approved">Approve saved profile</button><button name="decision" value="withdrawn">Withdraw consent</button></form></section></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function handlePost(PDO $db,string $basePath,array $user,?array $production):never
    {
        if(!hash_equals((string)($_SESSION['playbill_csrf']??''),(string)($_POST['csrf_token']??''))&&!(isset($_SESSION['playbill2_csrf'])&&hash_equals((string)$_SESSION['playbill2_csrf'],(string)($_POST['csrf_token']??'')))){self::flash('error','Your Playbill session expired. Please try again.');self::redirect($basePath.'/admin/playbill');}if(!$production){self::flash('error','Select an active production before managing its Playbill.');self::redirect($basePath.'/production');}
        try{$action=(string)($_POST['action']??'');$pb=self::playbillForProduction($db,(int)$production['id']);
        if(!PlaybillStudioService::canEdit($db,$user,(int)$production['id']))throw new RuntimeException('Current production editing permission is required.');
        if(isset($_POST['production_id'])&&(int)$_POST['production_id']!==(int)$production['id'])throw new RuntimeException('The working production changed. Reload this Studio before saving.');
        if(isset($_POST['playbill_id'])&&(int)$_POST['playbill_id']!==(int)($pb['id']??0))throw new RuntimeException('This program changed. Reload before saving.');
        if(!in_array($action,['unpublish','archive'],true))PlaybillStudioService::assertEditable($db,$user,$production,$pb);
        if(in_array($action,['artwork','cover_display','save_cast','save_sponsor','attach_sponsor','remove_sponsor','approve_own_profile'],true)){
            if(!$pb)throw new RuntimeException('Create the Playbill first.');$id=(int)$pb['id'];$actor=(int)$user['id'];
            if($action==='artwork')PlaybillEnhancementService::saveArtwork($db,dirname(__DIR__),$id,$actor,$_FILES['artwork']??[]);
            elseif($action==='cover_display'){$mode=(string)($_POST['cover_display']??'artwork_and_text');if(!in_array($mode,['artwork_and_text','artwork_only'],true))throw new RuntimeException('Choose a cover presentation.');$db->prepare('UPDATE playbills SET cover_display=? WHERE id=?')->execute([$mode,$id]);}
            elseif($action==='save_cast'){$person=(int)($_POST['user_id']??0);if($person<0)PlaybillEnhancementService::saveManualCastProfile($db,$id,-$person,$actor,$_POST);else PlaybillEnhancementService::saveCastProfile($db,dirname(__DIR__),$id,$person,$actor,$_POST,$_FILES['headshot']??[]);}
            elseif($action==='approve_own_profile'){$q=$db->prepare('SELECT id FROM playbill_cast_profiles WHERE playbill_id=? AND user_id=?');$q->execute([$id,$actor]);PlaybillEnhancementService::decideCastApproval($db,$user,(int)$q->fetchColumn(),'approved');}
            elseif($action==='save_sponsor'){$sponsor=PlaybillEnhancementService::saveSponsor($db,dirname(__DIR__),$actor,$_POST,$_FILES['logo']??[],$_FILES['advertisement']??[]);PlaybillEnhancementService::attachSponsor($db,$id,$sponsor,(string)($_POST['placement_label']??''),(int)($_POST['sort_order']??0),$actor,(string)($_POST['placement_format']??'card'));}
            elseif($action==='attach_sponsor')PlaybillEnhancementService::attachSponsor($db,$id,(int)($_POST['sponsor_id']??0),(string)($_POST['placement_label']??''),(int)($_POST['sort_order']??0),$actor,(string)($_POST['placement_format']??'card'));
            else PlaybillEnhancementService::removeSponsor($db,$id,(int)($_POST['sponsor_id']??0),$actor);
            self::flash('success','Saved to this unpublished program. Preview, then publish when ready.');
        }elseif($action==='import_team'){ $pb=self::playbillForProduction($db,(int)$production['id']);if(!$pb)throw new RuntimeException('Create the Playbill first.');ProductionTeamPublicationService::import($db,(int)$production['id'],(int)$pb['id'],(int)$user['id'],(string)($_POST['team_fingerprint']??''));self::flash('success','Reviewed name/title credits imported to the unpublished Playbill. Publish separately.');}elseif($action==='save_playbill'){self::savePlaybill($db,$user,$production,$_POST);self::flash('success','Playbill details saved.');}elseif($action==='save_section'){self::saveSection($db,$user,$production,$_POST);self::flash('success','Playbill section saved.');}elseif($action==='toggle_section'){self::toggleSection($db,$user,$production,(int)(filter_input(INPUT_POST,'section_id',FILTER_VALIDATE_INT)?:0));self::flash('success','Section visibility updated.');}elseif($action==='review'){self::changeStatus($db,$user,$production,'review');self::flash('success','Playbill moved to review.');}elseif($action==='publish'){self::changeStatus($db,$user,$production,'published');self::flash('success','Playbill published.');}elseif($action==='archive'){self::changeStatus($db,$user,$production,'archived');self::flash('success','Playbill archived and remains public.');}elseif($action==='unpublish'){self::changeStatus($db,$user,$production,'unpublished');self::flash('success','Playbill withdrawn from public access.');}else throw new RuntimeException('Choose a valid Playbill action.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}self::redirect($basePath.'/admin/playbill?production='.(int)$production['id'].'&tab='.rawurlencode((string)($_POST['studio_tab']??'overview')));
    }

    private static function savePlaybill(PDO $db,array $actor,array $production,array $input):void
    {
        $title=trim((string)($input['display_title']??''));$subtitle=trim((string)($input['subtitle']??''));$cover=trim((string)($input['cover_note']??''));$slug=strtolower(trim((string)($input['public_slug']??'')));$slug=trim(preg_replace('/[^a-z0-9-]+/','-',$slug)?:'','-');if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a Playbill title no longer than 190 characters.');if(mb_strlen($subtitle)>255)throw new RuntimeException('Keep the subtitle under 255 characters.');if(mb_strlen($cover)>500)throw new RuntimeException('Keep the cover note under 500 characters.');if($slug===''||mb_strlen($slug)>190)throw new RuntimeException('Enter a valid public slug.');
        $extra=null;if(array_key_exists('public_description',$input)){$extra=['description'=>trim((string)$input['public_description'])];if(mb_strlen($extra['description'])>500)throw new RuntimeException('Keep the program description under 500 characters.');foreach(['website_url','upcoming_url','donate_url'] as $field){$value=trim((string)($input[$field]??''));if($value!==''&&(!filter_var($value,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($value,PHP_URL_SCHEME)),['https','http'],true)))throw new RuntimeException('Program links must use a full http or https address.');$extra[$field]=$value?:null;}}
        $db->beginTransaction();try{$s=$db->prepare('SELECT id,status,public_slug,published_at FROM playbills WHERE production_id=:production LIMIT 1 FOR UPDATE');$s->execute(['production'=>(int)$production['id']]);$existing=$s->fetch();if($existing){if($existing['published_at']&&$slug!==$existing['public_slug'])throw new RuntimeException('Published program links are permanent. Keep the existing public address.');$db->prepare('UPDATE playbills SET display_title=:title,subtitle=:subtitle,cover_note=:cover,public_slug=:slug WHERE id=:id')->execute(['title'=>$title,'subtitle'=>$subtitle!==''?$subtitle:null,'cover'=>$cover!==''?$cover:null,'slug'=>$slug,'id'=>(int)$existing['id']]);$id=(int)$existing['id'];$event='playbill.updated';}else{$db->prepare("INSERT INTO playbills (production_id,display_title,subtitle,cover_note,status,public_slug,created_by_user_id) VALUES (:production,:title,:subtitle,:cover,'draft',:slug,:creator)")->execute(['production'=>(int)$production['id'],'title'=>$title,'subtitle'=>$subtitle!==''?$subtitle:null,'cover'=>$cover!==''?$cover:null,'slug'=>$slug,'creator'=>(int)$actor['id']]);$id=(int)$db->lastInsertId();$event='playbill.created';}if($extra!==null)$db->prepare('UPDATE playbills SET public_description=?,website_url=?,upcoming_url=?,donate_url=? WHERE id=?')->execute([$extra['description']?:null,$extra['website_url'],$extra['upcoming_url'],$extra['donate_url'],$id]);self::audit($db,(int)$actor['id'],$event,'playbill',$id,'Saved digital Playbill details.',['production_id'=>(int)$production['id'],'slug'=>$slug]);$db->commit();}catch(PDOException $e){if($db->inTransaction())$db->rollBack();if((string)$e->getCode()==='23000')throw new RuntimeException('That public slug is already in use. Choose another.');throw new RuntimeException('The Playbill could not be saved.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The Playbill could not be saved.');}
    }

    private static function saveSection(PDO $db,array $actor,array $production,array $input):void
    {
        $playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill)throw new RuntimeException('Save the Playbill cover details before adding sections.');$id=(int)(filter_input(INPUT_POST,'section_id',FILTER_VALIDATE_INT)?:0);$type=trim((string)($input['section_type']??'custom'));$heading=trim((string)($input['heading']??''));$body=trim((string)($input['body']??''));$order=(int)($input['sort_order']??0);if($heading===''||mb_strlen($heading)>190)throw new RuntimeException('Enter a section heading no longer than 190 characters.');if($body===''||mb_strlen($body)>20000)throw new RuntimeException('Enter section content up to 20,000 characters.');if($type===''||mb_strlen($type)>80)throw new RuntimeException('Choose a valid section type.');
        if($type==='production_team_snapshot')throw new RuntimeException('Production Team snapshots can only be created by reviewing source team credits.');
        if($id>0){$reserved=$db->prepare('SELECT section_type FROM playbill_sections WHERE id=? AND playbill_id=?');$reserved->execute([$id,(int)$playbill['id']]);if($reserved->fetchColumn()==='production_team_snapshot')throw new RuntimeException('Review and import source team credits instead of editing their snapshot.');}
        if($id>0){$s=$db->prepare('UPDATE playbill_sections SET section_type=:type,heading=:heading,body=:body,sort_order=:sort_order WHERE id=:id AND playbill_id=:playbill');$s->execute(['type'=>$type,'heading'=>$heading,'body'=>$body,'sort_order'=>$order,'id'=>$id,'playbill'=>(int)$playbill['id']]);$event='playbill.section_updated';}else{$s=$db->prepare('INSERT INTO playbill_sections (playbill_id,section_type,heading,body,sort_order,active) VALUES (:playbill,:type,:heading,:body,:sort_order,1)');$s->execute(['playbill'=>(int)$playbill['id'],'type'=>$type,'heading'=>$heading,'body'=>$body,'sort_order'=>$order]);$id=(int)$db->lastInsertId();$event='playbill.section_created';}self::audit($db,(int)$actor['id'],$event,'playbill_section',$id,'Saved Playbill section.',['playbill_id'=>(int)$playbill['id'],'production_id'=>(int)$production['id']]);
    }

    private static function toggleSection(PDO $db,array $actor,array $production,int $sectionId):void{$playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill||$sectionId<1)throw new RuntimeException('That Playbill section could not be found.');$s=$db->prepare('SELECT id,active,section_type FROM playbill_sections WHERE id=:id AND playbill_id=:playbill');$s->execute(['id'=>$sectionId,'playbill'=>(int)$playbill['id']]);$row=$s->fetch();if(!$row)throw new RuntimeException('That section does not belong to this Playbill.');if($row['section_type']==='production_team_snapshot')throw new RuntimeException('Review source team credits in an unpublished Playbill instead of toggling snapshots.');$next=(int)$row['active']?0:1;$db->prepare('UPDATE playbill_sections SET active=:active WHERE id=:id')->execute(['active'=>$next,'id'=>$sectionId]);self::audit($db,(int)$actor['id'],'playbill.section_visibility_changed','playbill_section',$sectionId,'Changed Playbill section visibility.',['active'=>(bool)$next]);}
    private static function changeStatus(PDO $db,array $actor,array $production,string $status):void
    {
        if(!in_array($status,['review','published','archived','unpublished'],true))throw new RuntimeException('Choose a valid Playbill status.');
        $playbill=self::playbillForProduction($db,(int)$production['id']);if(!$playbill)throw new RuntimeException('Create the Playbill before changing its publication status.');
        if($status==='published'){
            if(empty($playbill['public_slug']))throw new RuntimeException('Add a permanent public slug before publishing.');
            $q=$db->prepare("SELECT COUNT(*) FROM playbill_cast_profiles WHERE playbill_id=:id AND visible=1 AND approval_status<>'approved'");$q->execute(['id'=>(int)$playbill['id']]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Every visible performer profile must be approved before publishing.');$q=$db->prepare('SELECT COUNT(*) FROM playbill_manual_profiles WHERE playbill_id=:id AND visible=1 AND approve_public_name=0');$q->execute(['id'=>(int)$playbill['id']]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Every visible manual participant must have public-name approval before publishing.');
        }
        $db->beginTransaction();try{
            if($status==='unpublished'){$db->prepare("UPDATE playbills SET public_enabled=0,status=IF(editorial_status='archived','archived','draft'),editorial_status=IF(editorial_status='archived','archived','review'),unpublished_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>(int)$playbill['id']]);}
            else{$legacy=$status==='published'?'current':($status==='archived'?'archived':'draft');$public=$status==='published'?1:($status==='archived'?(int)$playbill['public_enabled']:0);$db->prepare('UPDATE playbills SET status=:legacy,editorial_status=:editorial,public_enabled=:public,published_at=IF(:published=1,COALESCE(published_at,CURRENT_TIMESTAMP),published_at),unpublished_at=NULL WHERE id=:id')->execute(['legacy'=>$legacy,'editorial'=>$status,'public'=>$public,'published'=>$public,'id'=>(int)$playbill['id']]);}
            if($status==='published')self::snapshotEdition($db,(int)$playbill['id'],(int)$actor['id']);
            self::audit($db,(int)$actor['id'],'playbill.status_changed','playbill',(int)$playbill['id'],'Changed Playbill publication status.',['status'=>$status,'production_id'=>(int)$production['id']]);$db->commit();
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e instanceof RuntimeException?$e:new RuntimeException('The publication status could not be changed.');}
    }
    private static function snapshotEdition(PDO $db,int $playbillId,int $actorId):void
    {
        $tables=['playbill_sections','playbill_cast_profiles','playbill_manual_profiles','playbill_sponsors'];$snapshot=[];foreach($tables as $table){$order=$table==='playbill_sponsors'?'sponsor_id':'id';$s=$db->prepare("SELECT * FROM `$table` WHERE playbill_id=:id ORDER BY `$order`");$s->execute(['id'=>$playbillId]);$snapshot[$table]=$s->fetchAll();}$s=$db->prepare('SELECT * FROM playbills WHERE id=:id');$s->execute(['id'=>$playbillId]);$snapshot['playbill']=$s->fetch();$n=$db->prepare('SELECT COALESCE(MAX(edition_number),0)+1 FROM playbill_editions WHERE playbill_id=:id');$n->execute(['id'=>$playbillId]);$db->prepare('INSERT INTO playbill_editions (playbill_id,edition_number,snapshot_json,published_by_user_id) VALUES (:id,:edition,:snapshot,:actor)')->execute(['id'=>$playbillId,'edition'=>(int)$n->fetchColumn(),'snapshot'=>json_encode($snapshot,JSON_THROW_ON_ERROR),'actor'=>$actorId]);
    }
    private static function playbillForProduction(PDO $db,int $productionId):?array{$s=$db->prepare('SELECT pb.*,p.title production_title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.production_id=:production ORDER BY pb.id DESC LIMIT 1');$s->execute(['production'=>$productionId]);return $s->fetch()?:null;}

    private static function page(PDO $db,string $route,string $basePath,array $user,?array $production,?array $playbill,array $sections,array $roster):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playbill</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><?php WorkspaceUI::operationsStyles($basePath);MemberUI::styles($basePath);?></head><body class="app-body ux-operations ux-workspace<?=MemberUI::bodyClass()?>"><div class="unified-shell"><?php AppNavigation::renderSidebar('/playbills',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production','Playbill',$basePath);?><section class="pb-page ops-page"><h2>No public Playbill is available for this production.</h2><p>Programs open here when explicitly published.</p><?php if(AccessPolicy::canManagePlaybill($user)):?><a href="<?=$u('/admin/playbill')?>">Open Playbill Studio</a><?php endif;?></section></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $metadata):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:metadata)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'metadata'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}
    private static function flash(string $type,string $message):void{$_SESSION['playbill_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);header('Content-Type:text/plain; charset=utf-8');echo 'Playbill management permission is required.';exit;}
}
